commit 83a9c210feffefa24d7f6ab2fbce64792c25946b
Author: K.Kosako <kosako@sofnec.co.jp>
Date:   Tue Jan 21 10:34:50 2020 +0900

    don't optimize look-behind if it includes captures or anchors

diff --git a/src/regcomp.c b/src/regcomp.c
index 6740d97..b79da4b 100644
--- a/src/regcomp.c
+++ b/src/regcomp.c
@@ -831,6 +831,8 @@ node_char_len1(Node* node, regex_t* reg, MinMaxCharLen* ci, ScanEnv* env,
           if (ci->min_is_sure != 0)
             NODE_STATUS_ADD(node, FIXED_CLEN_MIN_SURE);
         }
+        /* can't optimize look-behind if capture exists. */
+        ci->min_is_sure = FALSE;
         break;
       case BAG_OPTION:
       case BAG_STOP_BACKTRACK:
@@ -868,6 +870,11 @@ node_char_len1(Node* node, regex_t* reg, MinMaxCharLen* ci, ScanEnv* env,
     break;

   case NODE_ANCHOR:
+    mmcl_set(ci, 0);
+    /* can't optimize look-behind if anchor exists. */
+    ci->min_is_sure = FALSE;
+    break;
+
   case NODE_GIMMICK:
   zero:
     mmcl_set(ci, 0);
